import unittest

from solution import is_well_nested


class IsWellNestedTests(unittest.TestCase):
    def test_empty_and_simple_pairs(self):
        self.assertTrue(is_well_nested(""))
        for text in ("()", "[]", "{}", "()[]{}"):
            with self.subTest(text=text):
                self.assertTrue(is_well_nested(text))

    def test_deep_and_mixed_valid_nesting(self):
        for text in ("({[]})", "[({})]", "{{[()]}}", "([]{})"):
            with self.subTest(text=text):
                self.assertTrue(is_well_nested(text))

    def test_unmatched_closing_brackets(self):
        for text in (")", "]", "}", ")(", "())", "[]}"):
            with self.subTest(text=text):
                self.assertFalse(is_well_nested(text))

    def test_unclosed_or_misordered_brackets(self):
        for text in ("(", "[", "{", "(()", "([)]", "{]", "((]"):
            with self.subTest(text=text):
                self.assertFalse(is_well_nested(text))

    def test_non_bracket_characters_raise_value_error(self):
        for text in ("a", "(a)", " ", "\n", "()1", "🙂"):
            with self.subTest(text=text):
                with self.assertRaises(ValueError):
                    is_well_nested(text)

    def test_non_strings_raise_type_error(self):
        for value in (None, 1, True, [], ("(", ")")):
            with self.subTest(value=value):
                with self.assertRaises(TypeError):
                    is_well_nested(value)

    def test_calls_have_no_shared_state(self):
        self.assertFalse(is_well_nested("("))
        self.assertTrue(is_well_nested("[]"))
        self.assertFalse(is_well_nested("]"))
        self.assertTrue(is_well_nested("{}"))


if __name__ == "__main__":
    unittest.main()

